code_example:
#include <iostream>
#include <set>

int main() {
    std::set<int> c1 = {1, 2, 3};
    std::set<int> c2 = {1, 2, 3};
    std::set<int> c3 = {4, 5, 6};

    // Comparing containers using operators
    std::cout << std::boolalpha;
    std::cout << "c1 == c2: " << (c1 == c2) << '\n';
    std::cout << "c1 != c3: " << (c1 != c3) << '\n';
    std::cout << "c1 < c3: " << (c1 < c3) << '\n';
    std::cout << "c3 > c2: " << (c3 > c2) << '\n';
    std::cout << "c1 <= c2: " << (c1 <= c2) << '\n';
    std::cout << "c3 >= c1: " << (c3 >= c1) << '\n';
    return 0;
}
